    amount: $("lnAmount"),
    presets: $("lnPresets"),
    term: $("lnTerm"),
    termUnit: $("lnTermUnit"),
    promoToggle: $("lnPromoToggle"),
    promo: $("lnPromo"),
    promoBox: $("lnPromoBox"),
    promoRate: $("lnPromoRate"),
    promoMonths: $("lnPromoMonths"),
    rateLabel: $("lnRateLabel"),
    rate: $("lnRate"),
    status: $("status"),
    summary: $("lnSummary"),
    bar: $("lnBar"),
    compare: $("lnCompare"),
    rows: $("lnRows"),
